file.content:
.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }
/* Red build/perf pill — version + live average reschedule (buildSchedule) time. */
.perf-pill {
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  font-size: 0.64rem; font-weight: 800; letter-spacing: 0.03em;
  color: #fff; background: var(--warn); border-radius: 999px; padding: 5px 11px;
  font-variant-numeric: tabular-nums; cursor: default;
}
.perf-pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: #fff; flex: 0 0 auto; }
/* Testing-only chip — a loud red affordance (matching the "Now" app's DEBUG
   chip) that seeds the favourites UI with a random show set. */
.debug-chip {
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  font: inherit; font-size: 0.64rem; font-weight: 800; letter-spacing: 0.06em;
  text-transform: uppercase; color: #fff; background: var(--warn);
  border: none; border-radius: 999px; padding: 5px 11px; cursor: pointer;
}
.debug-chip::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: #fff; flex: 0 0 auto; }
.debug-chip:hover { filter: brightness(1.08); }
.debug-chip:active { transform: translateY(1px); }
.debug-chip:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
/* The header is a single nowrap flex row (~925px at full content), so a narrow
   page overflowed horizontally rather than reflowing. Drop the chrome
   progressively, least-important first, so logo + nav always fit: the decorative
   date tagline goes first, then the testing chip, then the telemetry pill. */
@media (max-width: 940px) { .header-hint { display: none; } }
@media (max-width: 700px) { .debug-chip { display: none; } }
@media (max-width: 500px) { .perf-pill { display: none; } }

