/* --- One neutral debug pill (version) that opens a dropdown of testing tools --- */
.debug-menu { position: relative; display: inline-flex; }
.debug-pill {
  display: inline-flex; align-items: center; gap: 7px; cursor: pointer; white-space: nowrap;
  font: inherit; font-size: 0.66rem; font-weight: 700; letter-spacing: 0.02em;
  color: var(--muted); background: var(--bg); border: 1px solid var(--line);
  border-radius: 999px; padding: 5px 12px; font-variant-numeric: tabular-nums;
}
.debug-pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: #c2c8d2; }
.debug-pill:hover { border-color: #d4d8e0; color: var(--ink); }
.debug-pill[aria-expanded="true"] { border-color: var(--red); color: var(--ink); }
.debug-pill:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
/* The dropdown card, anchored under the pill. */
.debug-pop {
  position: absolute; top: calc(100% + 8px); right: 0; z-index: 1600;
  display: flex; flex-direction: column; gap: 14px; min-width: 232px;
  background: var(--paper); color: var(--ink); border: 1px solid var(--line);
  border-radius: 12px; padding: 14px 16px; box-shadow: var(--shadow-soft);
  font-size: 0.82rem;
}
.debug-pop[hidden] { display: none; }
.debug-pop__now { margin: 0; font-weight: 700; font-size: 0.78rem; }
.debug-control { display: flex; flex-direction: column; gap: 6px; font-size: 0.64rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: var(--muted); }

