340	
341	/**
342	 * True if a slot starts no earlier than the day start, ends no later than the
343	 * day end, and overlaps none of the meal breaks — the day-hours filter the
344	 * scheduler applies before allocating.
345	 * @param {Slot} slot
346	 * @param {{dayStartMin?:number, dayEndMin?:number, mealBreaks?:Array<{startMin:number,endMin:number}>}} [win]
347	 * @returns {boolean}
348	 */
349	export function withinDayWindow(slot, win = {}) {
350	  const dayStartMin = win.dayStartMin ?? 0;
351	  const dayEndMin = win.dayEndMin ?? 1440;
352	  if (slot.startMinuteOfDay < dayStartMin) return false;
353	  if (slot.endMinuteOfDay > dayEndMin) return false;
354	  for (const b of win.mealBreaks || []) {
355	    // Overlap (half-open): a show touching a break edge-to-edge is fine.
356	    if (slot.startMinuteOfDay < b.endMin && slot.endMinuteOfDay > b.startMin) return false;
357	  }
358	  return true;
359	}
360	
361	/**
362	 * Minutes required between two slots. Same known venue → the same-venue buffer
363	 * (a double bill needs no travel). Different venues → the greater of the
364	 * different-venue buffer (a floor, also the value used when coordinates are
365	 * unknown) and the estimated door-to-door travel time by the chosen mode, so
366	 * the gap grows with distance and shrinks on a bike/car. Extends
367	 * scheduling.py's `required_gap_minutes` with the travel estimate.
368	 * @param {Slot} a
369	 * @param {Slot} b
370	 * @param {{minGapSameVenue?: number, minGapDifferentVenue?: number, travelMode?: string}} [options]
371	 * @returns {number}
372	 */
373	export function requiredGapMinutes(a, b, options = {}) {
374	  const minGapSameVenue = options.minGapSameVenue ?? DEFAULT_MIN_GAP_SAME_VENUE;
375	  const minGapDifferentVenue = options.minGapDifferentVenue ?? DEFAULT_MIN_GAP_DIFFERENT_VENUE;
376	  if (a.venueCode && b.venueCode && a.venueCode === b.venueCode) {
377	    return minGapSameVenue;
378	  }
379	  const t = travelMinutes(
380	    { lat: a.venueLat, lng: a.venueLng },
381	    { lat: b.venueLat, lng: b.venueLng },
382	    options.travelMode ?? DEFAULT_TRAVEL_MODE
383	  );
384	  if (t == null) return minGapDifferentVenue; // unknown coords — fall back to the flat buffer
385	  return Math.max(minGapDifferentVenue, Math.ceil(t));
386	}
387	
388	/**
389	 * True if both performances can be attended: no overlap, and at least the
390	 * required travel-buffer gap between them. Mirrors scheduling.py's `compatible`.
391	 * @param {Slot} a
392	 * @param {Slot} b
393	 * @param {{minGapSameVenue?: number, minGapDifferentVenue?: number}} [options]
394	 * @returns {boolean}
395	 */
396	export function compatible(a, b, options = {}) {
397	  const [earlier, later] = a.start <= b.start ? [a, b] : [b, a];
398	  return later.start >= earlier.end + requiredGapMinutes(earlier, later, options);
399	}
400	
