1338	function renderSchedule(schedule, animate = false) {
1339	  const host = $("schedule");
1340	  const empty = $("scheduleEmpty");
1341	  // Snapshot the outgoing board (block positions + which days were shown) before
1342	  // it's wiped, so the diff can play the right transition per block.
1343	  const prev = animate && !prefersReducedMotion() ? snapshotBoard(host) : null;
1344	  host.innerHTML = "";
1345	
1346	  if (schedule.days.length === 0) {
1347	    host.hidden = true;
1348	    empty.hidden = false;
1349	    state.schedAxis = null;
1350	    return;
1351	  }
1352	  host.hidden = false;
1353	  empty.hidden = true;
1354	
1355	  // Fixed festival axis: every day column runs 09:00 → 27:00 (03:00) so a late
1356	  // show has somewhere to land and the board never looks cramped or shifts as
1357	  // the plan changes. It only ever grows — never shrinks below that span — to
1358	  // hold an unusually early day-start or a show that runs to the small hours.
1359	  const mins = [AXIS_TOP_MIN, state.dayStartMin];
1360	  const maxs = [AXIS_BOTTOM_MIN, effectiveDayEnd()];
1361	  for (const slot of schedule.scheduled) {
1362	    mins.push(slot.startMinuteOfDay);
1363	    maxs.push(slot.endMinuteOfDay);
1364	  }
1365	  for (const m of state.mealBreaks) {
1366	    if (!m.enabled) continue;
1367	    mins.push(m.startMin);
1368	    maxs.push(m.endMin);
1369	  }
1370	  const lo = Math.max(0, Math.min(...mins));
1371	  const hi = Math.max(...maxs);
1372	  const minHour = Math.floor(lo / 60);
1373	  let maxHour = Math.ceil(hi / 60);
1374	  if (maxHour <= minHour) maxHour = minHour + 1;
1375	  const axisTopMin = minHour * 60;
1376	  const axisBottomMin = maxHour * 60;
1377	  const axisH = (maxHour - minHour) * SCH_HOUR_PX;
1378	  state.schedAxis = { axisTopMin, axisBottomMin, hourPx: SCH_HOUR_PX, headPx: SCH_HEAD_PX };
1379	  const y = (min) => ((clamp(min, axisTopMin, axisBottomMin) - axisTopMin) / 60) * SCH_HOUR_PX;
1380	
1381	  host.style.setProperty("--sch-hour-h", `${SCH_HOUR_PX}px`);
1382	  host.style.setProperty("--sch-head-h", `${SCH_HEAD_PX}px`);
1383	
1384	  // Left hour gutter. Past midnight the labels keep counting (24:00, 25:00, …)
1385	  // so the "same festival night" reads as one continuous evening.
1386	  const gutter = document.createElement("div");
1387	  gutter.className = "sch-gutter";
1388	  const gHead = document.createElement("div");
1389	  gHead.className = "sch-gutter-head";
1390	  const gBody = document.createElement("div");
1391	  gBody.className = "sch-gutter-body";
1392	  gBody.style.height = `${axisH}px`;
1393	  for (let h = minHour; h <= maxHour; h++) {
1394	    const lab = document.createElement("div");
1395	    lab.className = "sch-hour" + (h >= 24 ? " sch-hour--late" : "");
1396	    lab.style.top = `${(h - minHour) * SCH_HOUR_PX}px`;
1397	    lab.textContent = `${pad2(h)}:00`;
1398	    gBody.appendChild(lab);
1399	  }
1400	  gutter.append(gHead, gBody);
1401	  host.appendChild(gutter);
1402	
1403	  // One column per day; columns flex to share the width.
1404	  for (const day of schedule.days) {
1405	    const dayNum = Number(day.date.slice(8, 10));
1406	    const col = document.createElement("div");
1407	    col.className = "sch-day" + (isWeekend(dayNum) ? " wknd" : "");
1408	    col.dataset.date = day.date;
1409	
1410	    const head = document.createElement("div");
1411	    head.className = "sch-day-head";
1412	    head.innerHTML =
1413	      `<div class="sch-dow">${DOW_LONG[dow(dayNum)]} <span class="sch-date">${dayNum} Aug</span></div>` +
1414	      `<div class="sch-day-count">${day.slots.length} show${day.slots.length === 1 ? "" : "s"}</div>`;
1415	
1416	    const body = document.createElement("div");
1417	    body.className = "sch-body";
1418	    body.style.height = `${axisH}px`;
1419	
1420	    // Travel legs between consecutive shows less than an hour apart.
1421	    for (let i = 0; i < day.slots.length - 1; i++) {
1422	      const a = day.slots[i];
1423	      const b = day.slots[i + 1];
1424	      const gapMin = b.startMinuteOfDay - a.endMinuteOfDay;
1425	      if (gapMin < 0 || gapMin >= 60) continue;
1426	      body.appendChild(buildTravelLeg(a, b, y(a.endMinuteOfDay), y(b.startMinuteOfDay)));
1427	    }
1428	
1429	    for (const slot of day.slots) {
1430	      body.appendChild(buildScheduleBlock(slot, y(slot.startMinuteOfDay), y(slot.endMinuteOfDay)));
1431	    }
1432	
1433	    col.append(head, body);
1434	    host.appendChild(col);
1435	  }
1436	
1437	  // Draggable overlay: day-start / day-end lines + meal bands.
1438	  host.appendChild(buildScheduleOverlay(axisH, y));
1439	
1440	  // Animate what actually changed since the last board: shows arrive, depart, or
1441	  // fly to a new slot; brand-new day columns ease in.
1442	  if (prev) animateBoardDiff(host, prev);
1443	}
