/* Meal-break band: draggable to move, edge handles to resize. Its background
   now matches the "before day starts / after day ends" zones (a neutral
   diagonal hatch) so every "you can't be here" region on the board reads the
   same; only the 🍽 label carries the meal identity. */
.sch-meal {
  position: absolute; left: 0; right: 0; z-index: 5;
  background: repeating-linear-gradient(-45deg, rgba(16,24,40,0.05) 0 6px, rgba(16,24,40,0.02) 6px 12px);
  border-block: 1px solid rgba(16, 24, 40, 0.08);
  cursor: grab; pointer-events: auto; touch-action: none; overflow: hidden;
}
.sch-meal.dragging { cursor: grabbing; }
.sch-meal .meal-label {
  position: absolute; top: 50%; left: 6px; transform: translateY(-50%);
  font-size: 0.6rem; font-weight: 700; color: var(--muted); white-space: nowrap;
  font-variant-numeric: tabular-nums; pointer-events: none;
}
.sch-meal .meal-resize { position: absolute; left: 0; right: 0; height: 7px; cursor: ns-resize; }
.sch-meal .meal-resize--top { top: -1px; }
.sch-meal .meal-resize--bottom { bottom: -1px; }

/* "Getting there" / "getting out" blocks — one per trip, inside their own day
   column (behind the shows). Same hatch as the zones/meals; drag the inner edge
   to resize. */
.sch-trip {
  position: absolute; left: 0; right: 0;
  background: repeating-linear-gradient(-45deg, rgba(16,24,40,0.05) 0 6px, rgba(16,24,40,0.02) 6px 12px);
  border-block: 1px solid rgba(16, 24, 40, 0.08);
  pointer-events: auto; touch-action: none; overflow: hidden;
}
.sch-trip .sch-trip-label {
  position: absolute; left: 6px; right: 6px;
  font-size: 0.6rem; font-weight: 700; color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font-variant-numeric: tabular-nums; pointer-events: none;
}
.sch-trip--arrival .sch-trip-label { bottom: 4px; }
.sch-trip--departure .sch-trip-label { top: 4px; }
.sch-trip.dragging {
  background: repeating-linear-gradient(-45deg, rgba(108,76,241,0.12) 0 6px, rgba(108,76,241,0.04) 6px 12px);
}
.sch-trip .meal-resize { position: absolute; left: 0; right: 0; height: 9px; cursor: ns-resize; touch-action: none; }
.sch-trip .meal-resize--top { top: -2px; }
.sch-trip .meal-resize--bottom { bottom: -2px; }

