1	// Tests for the planner's new scheduling logic: travel-time gaps, the
2	// day-hours window, meal breaks, and forced (must-see) scheduling. Plain
3	// node:test + node:assert, no dependencies.
4	//   node --test plan/lib/__tests__/planning.test.mjs
5	
6	import { test } from "node:test";
7	import assert from "node:assert/strict";
8	
9	import {
10	  buildSchedule,
11	  eligibleSlots,
12	  slotKey,
13	  requiredGapMinutes,
14	  compatible,
15	  withinDayWindow,
16	  normalizeMealBreaks,
17	  festivalNight,
18	  placementDiagnostics,
19	} from "../engine.js";
20	import { distanceKm, travelMinutes, TRAVEL_SPEED_KMH } from "../travel.js";
21	
22	// --- Fixtures ------------------------------------------------------------
23	
24	// Two venues ~2 km apart (same longitude, ~0.018° of latitude ≈ 2 km at
25	// Edinburgh). At that distance a walk (≈36 min) exceeds the 30-min flat buffer
26	// but a bike/car (≈8/≈5 min) does not — the lever the travel-mode tests pull.
27	const VENUE_COORDS = {
28	  A: { lat: 55.9478, lng: -3.1861 },
29	  B: { lat: 55.9658, lng: -3.1861 },
30	  ONLINE: { lat: null, lng: null },
31	};
32	
33	function show(slug, venue, perfs, extra = {}) {
34	  return {
35	    slug,
36	    title: slug,
37	    genre: "Comedy",
38	    duration: 60,
39	    venue,
40	    venueName: venue,
41	    performances: perfs.map((p) => ({
42	      date: p.date ?? "2026-08-10",
43	      start: p.start,
44	      soldOut: false,
45	      status: p.status ?? "TICKETS_AVAILABLE",
46	    })),
47	    ...extra,
48	  };
49	}
50	
51	const WIDE = { windowStart: "2026-08-01T00:00", windowEnd: "2026-08-31T23:59" };
52	
53	// --- travel.js -----------------------------------------------------------
54	
55	test("distanceKm: ~2 km between the two fixture venues, null when a coord is missing", () => {
56	  const d = distanceKm(VENUE_COORDS.A, VENUE_COORDS.B);
57	  assert.ok(d > 1.9 && d < 2.1, `expected ~2 km, got ${d}`);
58	  assert.equal(distanceKm(VENUE_COORDS.A, VENUE_COORDS.ONLINE), null);
59	  assert.equal(distanceKm(VENUE_COORDS.A, null), null);
60	});
61	
62	test("travelMinutes: walk slower than bike slower than car; null on missing coords", () => {
63	  const walk = travelMinutes(VENUE_COORDS.A, VENUE_COORDS.B, "walk");
64	  const bike = travelMinutes(VENUE_COORDS.A, VENUE_COORDS.B, "bike");
65	  const car = travelMinutes(VENUE_COORDS.A, VENUE_COORDS.B, "car");
66	  assert.ok(walk > bike && bike > car, `walk ${walk} > bike ${bike} > car ${car}`);
67	  assert.ok(TRAVEL_SPEED_KMH.walk < TRAVEL_SPEED_KMH.bike);
68	  assert.equal(travelMinutes(VENUE_COORDS.A, VENUE_COORDS.ONLINE, "walk"), null);
69	});
70	
71	// --- requiredGapMinutes / compatible with travel -------------------------
72	
73	test("requiredGapMinutes: travel time drives the different-venue gap, floored at the buffer", () => {
74	  const slots = eligibleSlots(
75	    [show("a", "A", [{ start: "12:00" }]), show("b", "B", [{ start: "14:00" }])],
76	    { ...WIDE, venueCoords: VENUE_COORDS }
77	  );
78	  const a = slots.get("a")[0];
79	  const b = slots.get("b")[0];
80	  const walkGap = requiredGapMinutes(a, b, { minGapDifferentVenue: 30, travelMode: "walk" });
